        if not client.is_running():
            return None, False
        raw = client.get_state("phase")
        return raw, True
    except Exception:
        return None, False


def _release_badge() -> str:
    """A compact ``  ↑<version>`` suffix when a newer release is available, else "".

    Cache-only (never touches the network) and fully fail-silent so it can never
    break the per-turn status line. The producer is the running service.
=== task 168-182 ===
    When the phase state service is running, the read is routed through
    the service's HTTP API; otherwise the file-mirror path is used.
    """
    client = StateClient()
    if client.is_running():
        try:
            raw = client.get_state("cursor")
            if raw is not None:
                return {"ok": True, "cursor": raw.strip()}
        except StateClientError as exc:
            print(
                f"Warning: state service returned {exc.status}: {exc.message}; "
                f"falling back to file-mirror read.",
                file=sys.stderr,
            )

